package android.bluetooth; import android.content.Context;import java.util.*;public class BluetoothAdapter {public boolean enabled=true;public boolean denyPermission;public final BluetoothHidDevice device;public final Set<BluetoothDevice> bonded=new LinkedHashSet<>();public int closed;public BluetoothProfile.ServiceListener listener;public BluetoothAdapter(BluetoothHidDevice device){this.device=device;}public boolean isEnabled(){if(denyPermission)throw new SecurityException();return enabled;}public boolean getProfileProxy(Context c,BluetoothProfile.ServiceListener l,int profile){listener=l;l.onServiceConnected(profile,device);return true;}public Set<BluetoothDevice> getBondedDevices(){return bonded;}public void closeProfileProxy(int profile,BluetoothProfile proxy){closed++;}}
